#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    string s;
    cin >> s;

    vector<int> divisors;
    for (int i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            divisors.push_back(i);
            if (i * i != n && i != 1) {
                divisors.push_back(n / i);
            }
        }
    }
    sort(divisors.begin(), divisors.end());

    for (int L : divisors) {
        vector<int> count_root(26, 0);
        for (int i = 0; i < L; ++i) {
            count_root[s[i] - 'a']++;
        }

        bool ok = true;
        for (int i = L; i < n; i += L) {
            vector<int> count_block(26, 0);
            for (int j = 0; j < L; ++j) {
                count_block[s[i + j] - 'a']++;
            }
            if (count_block != count_root) {
                ok = false;
                break;
            }
        }

        if (ok) {
            cout << s.substr(0, L) << "\n";
            return 0;
        }
    }

    cout << "*\n";
    return 0;
}
